            let r = Resolver(ctx)
            let c = try r.course(course)
            let action = FolioActions.QuizCardSave(
                course: c.id,
                cards: try readJSONFile([QuizCard].self, cards),
                movedFrom: try movedFrom.map { try r.id("Unit", $0, in: c) }
            )
            try perform(spec: action, g, ctx: ctx)
        }
    }

